        public static UnitConverterLengthUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterLengthUnit>();
            for (int i = 0; i < 101; i++) if (GetUnitSystem((UnitConverterLengthUnit)i) == system) units.Add((UnitConverterLengthUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterLengthUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterLengthUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterLengthUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterLengthUnit)id : default(UnitConverterLengthUnit); return success;
        }

        public static UnitConverterLengthUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterLengthUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous Length unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterLengthValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterLengthValue(value, (UnitConverterLengthUnit)id) : default(UnitConverterLengthValue); return success;
        }

        public static UnitConverterLengthValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterLengthValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous Length unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterLengthUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


